"""
RoninPlanner class managing prompt generation and closed-loop ReAct planning via the LLM.
"""

import json
import logging

from pydantic import BaseModel, Field

from actuation.actions import ActionPlan
from llm.llm_client import LLMClient
from llm.messages import MultiPartMessage

logger = logging.getLogger(__name__)


class AgentStepResponse(BaseModel):
    """Represents a single decision step generated by the ReAct planner."""
    is_done: bool = Field(
        ...,
        description="Set to True if the final goal has been successfully accomplished, otherwise False."
    )
    reasoning: str = Field(
        ...,
        description="Reasoning explaining the current screen state and the chosen action."
    )
    action: ActionPlan | None = Field(
        None,
        description="The ActionPlan (containing exactly one action) to perform next. Must be None if is_done is True."
    )


class RoninPlanner:
    """Manages AI-driven visual and logical closed-loop planning for mobile automation."""

    def __init__(self, llm_client: LLMClient, use_multimodal_vision: bool = False):
        """Initializes the RoninPlanner.

        Args:
            llm_client: The LLMClient instance to use for completion requests.
            use_multimodal_vision: If True, allows the LLM to override element coordinates.
        """
        self.llm = llm_client
        self.use_multimodal_vision = use_multimodal_vision

    def _format_elements_for_prompt(self, elements) -> str:
        """Formats detected GUI elements into a text description for LLM consumption."""
        lines = []
        for el in elements:
            cx = (el.bounding_box.x_min + el.bounding_box.x_max) // 2
            cy = (el.bounding_box.y_min + el.bounding_box.y_max) // 2
            if el.text:
                lines.append(f"- {el.element} | text: '{el.text}' | center: ({cx}, {cy})")
            else:
                lines.append(f"- {el.element} | center: ({cx}, {cy})")
        return "\n".join(lines)

    def plan_next_step(
        self,
        goal: str,
        gui_elements,
        current_image_bytes: bytes,
        visual_history: list[bytes],
        text_history: list[str],
    ) -> AgentStepResponse:
        """Generates the next logical step and action in the closed-loop ReAct sequence.

        Args:
            goal: The target goal of the E2E test.
            gui_elements: Detected elements on the current screen.
            current_image_bytes: Current screenshot image bytes.
            visual_history: List of past screenshot image bytes.
            text_history: List of previously executed actions as strings.

        Returns:
            An AgentStepResponse indicating if the task is done, the reasoning, and the next ActionPlan.
        """
        prompt_text = f"""You are a closed-loop mobile automation planning agent.
Your overall goal is: "{goal}"

### Current UI Elements Detected (YOLO/OCR)
{self._format_elements_for_prompt(gui_elements)}

### History of Executed Actions
{chr(10).join(f"- {act}" for act in text_history) if text_history else "No actions executed yet."}

### Instructions
1. Inspect the visual screenshots provided. You are given a sequence of past screen states, with the last image representing the current screen.
2. Determine if the goal has been fully achieved. If so, set `is_done = True` and `action = None`.
3. If not done, plan the single next action to execute. You must output EXACTLY one action in `action.actions` list.
"""

        if self.use_multimodal_vision:
            prompt_text += """
4. Prefer using the center coordinates of the detected UI elements. However, since multimodal override is ENABLED, if you visually detect a critical element that was missed by YOLO/OCR, or if the bounding box center is incorrect, you may specify custom coordinate overrides (x, y) based on your direct visual inspection of the screenshot.
"""
        else:
            prompt_text += """
4. You MUST strictly select and target the center coordinates of the detected UI elements listed above. Do not specify coordinates outside of the detected element bounding boxes.
"""

        message = MultiPartMessage()
        
        # Add visual history in chronological order
        for idx, img_bytes in enumerate(visual_history):
            message.add_text(f"Screenshot from step {idx + 1}:")
            message.add_image(img_bytes)
            
        # Add current screenshot
        message.add_text("Current screenshot (newest):")
        message.add_image(current_image_bytes)
        message.add_text(prompt_text)

        logger.info("Querying planner for next step...")
        response: AgentStepResponse = self.llm.generate_response([message], AgentStepResponse)
        return response
